export const quarterlyApi = {
  async getQuarterlyReports() {
    try {
      const response = await fetch(`${API_BASE_URL}/quarterly`);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      return await response.json();
    } catch (error) {
      console.error('Error fetching quarterly reports:', error);
      throw error;
