import { useNavigate, useParams } from 'react-router-dom';
import { quarterlyApi } from '../services/quarterlyApi';

const QuarterlyDashboard = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [report, setReport] = useState(null);
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (id) {
      loadQuarterlyReport();
    }
  }, [id]);

  const loadQuarterlyReport = async () => {
    try {
      setLoading(true);
      setError(null);
      const reportData = await quarterlyApi.getQuarterlyReportById(id);
      setReport(reportData);
      setInvoices(reportData?.invoices || []);
    } catch (err) {
      console.error('Error loading quarterly report:', err);
      setError('Failed to load quarterly report. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (value) => {
    const numericValue = Number(value);
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 2,
    }).format(Number.isFinite(numericValue) ? numericValue : 0);
  };

  const formatDate = (value) => {
    if (!value) return '—';
    const date = new Date(value);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-gray-500 dark:text-gray-400">Loading quarterly report...</p>
      </div>
    );
  }

  if (error || !report) {
    return (
      <div className="flex flex-col items-center justify-center h-full gap-4">
        <p className="text-red-500 dark:text-red-400">{error || 'Quarterly report not found'}</p>
        <button
          onClick={() => navigate('/quarterly')}
          className="px-4 py-2 bg-primary text-white rounded-xl hover:bg-sky-600 transition-colors"
        >
          Back to Quarterly Reports
        </button>
      </div>
    );
  }

  const quarterLabel = report?.quarter ? `Q${report.quarter}` : 'Quarter';
  const yearLabel = report?.year || '';

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <header className="flex justify-between items-center mb-6 pt-2 pr-4 shrink-0">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate('/quarterly')}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-xl transition-colors"
          >
            <span className="material-icons-outlined text-gray-600 dark:text-gray-400">arrow_back</span>
          </button>
          <div>
            <h2 className="text-3xl font-bold text-gray-900 dark:text-white">
              {quarterLabel} {yearLabel}
            </h2>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Quarterly Dashboard</p>
          </div>
        </div>
        <div className="text-sm text-gray-500 dark:text-gray-400">
          Generated {formatDate(report.generated_at)}
        </div>
      </header>

      <div className="bg-card-light dark:bg-card-dark rounded-3xl p-6 mb-6 mr-4 shadow-sm shrink-0">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="flex items-start gap-3">
            <div className="p-2 bg-gray-50 dark:bg-gray-800 rounded-lg shrink-0">
              <span className="material-icons-outlined text-gray-400">payments</span>
            </div>
            <div>
              <p className="text-xs text-gray-400 mb-1">Base Price</p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(report.total_base_price)}
              </p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <div className="p-2 bg-gray-50 dark:bg-gray-800 rounded-lg shrink-0">
              <span className="material-icons-outlined text-gray-400">receipt_long</span>
            </div>
            <div>
              <p className="text-xs text-gray-400 mb-1">GST</p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(report.total_gst)}
              </p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <div className="p-2 bg-gray-50 dark:bg-gray-800 rounded-lg shrink-0">
              <span className="material-icons-outlined text-gray-400">request_quote</span>
            </div>
            <div>
              <p className="text-xs text-gray-400 mb-1">QST</p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(report.total_qst)}
              </p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <div className="p-2 bg-gray-50 dark:bg-gray-800 rounded-lg shrink-0">
              <span className="material-icons-outlined text-gray-400">account_balance_wallet</span>
            </div>
            <div>
              <p className="text-xs text-gray-400 mb-1">Total</p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(report.total_price)}
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 min-h-0 flex flex-col pr-4">
        <div className="flex justify-between items-center mb-4 shrink-0">
          <h3 className="text-xl font-bold text-gray-900 dark:text-white">Invoices</h3>
          <span className="text-sm text-gray-500 dark:text-gray-400">
            {invoices.length} {invoices.length === 1 ? 'invoice' : 'invoices'}
